const STATES = LOCATIONS.map(s => s.state);

const CITIES_BY_STATE = Object.fromEntries(LOCATIONS.map(s => [s.state, s.cities]));

const ALL_CITIES = [...new Set(LOCATIONS.flatMap(s => s.cities))].sort();

// City -> state lookup, for deriving a legacy profile's state from its
// already-saved free-text city (first state wins on rare name collisions).
const STATE_OF_CITY = {};
LOCATIONS.forEach(s => {
  s.cities.forEach(c => {
    if (!(c in STATE_OF_CITY)) STATE_OF_CITY[c] = s.state;
  });
});

// A profile's chosen cities, normalized to an array regardless of whether it
// was saved on the new multi-select `cities` field or the legacy single
// `city` string — so every matching/filtering call site (discover, campaign
// audience, campaign relevance) only has to handle one shape. Returns []
// when the profile has set no location at all.
function profileCities(profile) {
  if (!profile) return [];
  if (Array.isArray(profile.cities) && profile.cities.length > 0) return profile.cities;
  if (profile.city) return [profile.city];
  return [];
}

module.exports = {
  LOCATIONS,
  STATES,
  CITIES_BY_STATE,
  ALL_CITIES,
  STATE_OF_CITY,
  profileCities,
};
